const source=$('IsRevenueReport').first().json.request_source||'manual';
const invoices=$('GetInvoicesForReport').all().map(x=>x.json).filter(x=>x.invoice_id&&!String(x.invoice_id).startsWith('SAMPLE'));
const payments=$('GetPaymentsForReport').all().map(x=>x.json).filter(x=>x.payment_id&&!String(x.payment_id).startsWith('SAMPLE')&&x.status==='recorded'&&Number(x.amount_usd)>0);
const money=n=>Math.round((Number(n)||0)*100)/100;
const paidByInvoice={};
for(const p of payments)paidByInvoice[p.invoice_id]=money((paidByInvoice[p.invoice_id]||0)+Number(p.amount_usd));
const issued=invoices.filter(i=>['issued','partially_paid','paid'].includes(i.invoice_status));
const draft=invoices.filter(i=>i.invoice_status==='draft_pending_review');
const today=new Date().toISOString().slice(0,10);
const as_of=new Date().toISOString();
let invoiced=0, received=0, outstanding=0, overdue=0;
const aging={'not_due':0,'1_30_days':0,'31_60_days':0,'61_plus_days':0};
const discrepancies=[];const overdueRows=[];
for(const inv of issued){
 const due=Number(inv.total_due_usd), ledgerPaid=money(paidByInvoice[inv.invoice_id]||0);
 if(!Number.isFinite(due)||due<=0){discrepancies.push('Invalid total on '+inv.invoice_id);continue;}
 invoiced+=due;received+=Math.min(due,ledgerPaid);
 const remain=money(Math.max(0,due-ledgerPaid));outstanding+=remain;
 if(Math.abs(money(inv.paid_amount_usd)-ledgerPaid)>0.009)discrepancies.push('Invoice balance / ledger mismatch: '+inv.invoice_id);
 if(ledgerPaid>due+0.009)discrepancies.push('Overpayment in payment ledger: '+inv.invoice_id);
 if(remain<=0)continue;
 if(inv.due_date&&inv.due_date<today){
  const days=Math.floor((Date.parse(today+'T00:00:00Z')-Date.parse(inv.due_date+'T00:00:00Z'))/86400000);
  overdue+=remain;overdueRows.push({invoice_id:inv.invoice_id,days_overdue:days,amount_usd:remain});
  if(days<=30)aging['1_30_days']+=remain;
  else if(days<=60)aging['31_60_days']+=remain;
  else aging['61_plus_days']+=remain;
 }else aging.not_due+=remain;
}
for(const k in aging)aging[k]=money(aging[k]);
const count=(n)=>Number(n).toLocaleString('en-US');
const fmt=n=>'USD '+money(n).toFixed(2);
const rows=overdueRows.sort((a,b)=>b.amount_usd-a.amount_usd).slice(0,10).map(x=>`| ${x.invoice_id} | ${x.days_overdue} | ${fmt(x.amount_usd)} |`).join('\n')||'| None | - | - |';
const report=`# P02 Revenue Intelligence (Internal Demo)\n\nGenerated: ${as_of}\n\n| KPI | Value |\n|---|---:|\n| Issued invoices | ${count(issued.length)} |\n| Draft invoices | ${count(draft.length)} |\n| Recorded payments | ${count(payments.length)} |\n| Total issued | ${fmt(invoiced)} |\n| Collected (ledger) | ${fmt(received)} |\n| Outstanding | ${fmt(outstanding)} |\n| Overdue | ${fmt(overdue)} |\n\n## Aging\n${Object.entries(aging).map(([k,v])=>'- '+k+': '+fmt(v)).join('\n')}\n\n## Top overdue\n| Invoice | Days overdue | Amount |\n|---|---:|---:|\n${rows}\n\n## Integrity checks\n${discrepancies.length?discrepancies.map(x=>'- '+x).join('\n'):'No ledger/invoice discrepancies detected.'}\n\n**Recorded amounts only.** This report is not bank reconciliation or financial advice.`;
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const dashboard_html='<h1>P02 Revenue Intelligence</h1><p>As of: '+esc(as_of)+' | Currency: USD</p>'
 +'<h2>Key metrics</h2><table><thead><tr><th>KPI</th><th>Value</th></tr></thead><tbody>'
 +[['Issued invoices',issued.length],['Draft invoices',draft.length],['Recorded payments',payments.length],['Total issued',fmt(invoiced)],['Total collected',fmt(received)],['Outstanding',fmt(outstanding)],['Overdue',fmt(overdue)]].map(([k,v])=>'<tr><td>'+esc(k)+'</td><td>'+esc(v)+'</td></tr>').join('')+'</tbody></table>'
 +'<h2>Outstanding aging</h2><table><thead><tr><th>Bucket</th><th>Amount</th></tr></thead><tbody>'
 +Object.entries(aging).map(([k,v])=>'<tr><td>'+esc(k)+'</td><td>'+esc(fmt(v))+'</td></tr>').join('')+'</tbody></table>'
 +'<h2>Top overdue invoices</h2><table><thead><tr><th>Invoice</th><th>Days</th><th>Outstanding</th></tr></thead><tbody>'
 +(overdueRows.length?overdueRows.slice(0,10).map(x=>'<tr><td>'+esc(x.invoice_id)+'</td><td>'+esc(x.days_overdue)+'</td><td>'+esc(fmt(x.amount_usd))+'</td></tr>').join(''):'<tr><td>No overdue invoices</td><td>-</td><td>-</td></tr>')+'</tbody></table>'
 +'<h2>Integrity checks</h2><p>'+esc(discrepancies.length?discrepancies.join(' | '):'No ledger discrepancies detected.')+'</p>'
 +'<p>Internal recorded-ledger figures, not verified bank reconciliation.</p>';
return {json:{snapshot_id:'REV-'+String($execution.id??Date.now()),as_of,currency:'USD',issued_invoices:issued.length,draft_invoices:draft.length,payment_count:payments.length,total_invoiced_usd:money(invoiced),total_collected_usd:money(received),outstanding_usd:money(outstanding),overdue_usd:money(overdue),aging_json:JSON.stringify(aging),discrepancies_json:JSON.stringify(discrepancies),report_markdown:report,report_html:dashboard_html,source,overdue_invoices:overdueRows}};

const v=$json,s=x=>String(x??'').trim();
const invoice_id=s(v.invoice_id),reference=s(v.payment_reference);
const rawAmount=s(v.amount_usd),amount=Number(rawAmount);
const paid_at=s(v.paid_at)||new Date().toISOString().slice(0,10);
const recorded_by=s(v.recorded_by), method=s(v.payment_method)||'Other';
const id=s(v.payment_id)||('PAY-'+invoice_id.replace(/[^A-Za-z0-9]/g,'').slice(-28)+'-'+reference.replace(/[^A-Za-z0-9]/g,'').slice(-35));
const valid=invoice_id.length>5&&reference.length>=3&&recorded_by.length>1&&rawAmount!==''&&Number.isFinite(amount)&&amount>0&&Math.abs(amount*100-Math.round(amount*100))<0.000001&&(/^\d{4}-\d{2}-\d{2}$/.test(paid_at) && !Number.isNaN(Date.parse(paid_at+'T00:00:00Z')) && new Date(paid_at+'T00:00:00Z').toISOString().slice(0,10)===paid_at)&&id.length>8;
return {json:{valid,reason:valid?'':'Valid issued invoice ID, positive 2-decimal amount, unique reference, payment date and recorder required.',invoice_id,payment_id:id,amount_usd:amount,payment_reference:reference,payment_method:method,paid_at,recorded_by,recorded_at:new Date().toISOString(),request_source:s(v.request_source),verification_status:'manual_record_not_bank_reconciled'}};

const p=$('NormalizePaymentEvent').first().json;
const invoice=$('GetInvoiceForPayment').first().json||{};
const duplicate=$('FindDuplicatePayment').first().json||{};
const ledger=$('GetInvoicePaymentLedger').all().map(x=>x.json).filter(x=>x.invoice_id===p.invoice_id&&x.status==='recorded');
const reasons=[];
if(ledger.some(x=>String(x.payment_reference??'').trim().toLowerCase()===p.payment_reference.toLowerCase()))reasons.push('Payment reference already recorded on this invoice');
if(invoice.invoice_id!==p.invoice_id)reasons.push('Invoice not found');
if(!['issued','partially_paid'].includes(invoice.invoice_status))reasons.push('Invoice not open for payment');
if(duplicate.payment_id)reasons.push('Payment reference/id already recorded');
const total=Number(invoice.total_due_usd);
if(!Number.isFinite(total)||total<=0)reasons.push('Invoice total invalid');
const already=Math.round(ledger.reduce((s,x)=>s+Number(x.amount_usd||0),0)*100)/100;
const remaining=Math.round((total-already)*100)/100;
const paid=Math.round((already+p.amount_usd)*100)/100;
if(p.amount_usd>remaining+0.000001)reasons.push('Overpayment blocked; remaining USD '+Math.max(remaining,0).toFixed(2));
if(Math.abs(Number(invoice.paid_amount_usd||0)-already)>0.009)reasons.push('Invoice/ledger mismatch; reconcile manually');
return {json:{...p,allowed:reasons.length===0,reason:reasons.join('; '),quote_id:invoice.quote_id||'',currency:invoice.currency||'USD',invoice_total_usd:total,already_paid_usd:already,new_paid_amount_usd:paid,remaining_before_usd:remaining,new_invoice_status:paid>=total-0.009?'paid':'partially_paid',status:'recorded'}};
